def _angular_nodes_from_grid(grid):
    """Return angular nodes from one radial surface of a DESC mesh grid."""

    nodes = getattr(grid, "nodes", None)
    if nodes is None:
        return None, None
    nodes = np.asarray(nodes, dtype=float)
    if nodes.ndim != 2 or nodes.shape[1] < 3:
        return None, None
    rho = nodes[:, 0]
    unique_rho = np.unique(rho)
    if unique_rho.size == 0 or nodes.shape[0] % unique_rho.size != 0:
        return None, None
    angular_count = nodes.shape[0] // unique_rho.size
    surface_mask = np.isclose(rho, unique_rho[0])
    angular_nodes = nodes[surface_mask]
    if angular_nodes.shape[0] != angular_count:
        return None, None
    return angular_nodes[:, 1], angular_nodes[:, 2]


def _fourin_trig_table(equilibrium_data, mode_table, nfp, nj, nk):
    """Build the FOURIN trigonometric table on the geometry's angular grid.

    The coefficient generation integrates real-space fields produced by the
    geometry stage, so the trigonometric tables must be sampled on exactly the
    same angular nodes.  When the strict geometry stage recorded its native
    angular sampling (``terpsichore_fourin_angles``) those nodes are
    authoritative; otherwise the equilibrium grid's angular nodes are used
    when available, and a uniform ``(nj, nk)`` mesh is the fallback.
    """

    angles = equilibrium_data.data.get("terpsichore_fourin_angles")
    if angles is not None:
        pol, tor = (np.asarray(values, dtype=float) for values in angles)
        return build_trig_table(mode_table, nj=pol.size, nk=1, nper=nfp, pol=pol, tor=tor)
    pol, tor = _angular_nodes_from_grid(equilibrium_data.grid)
    if pol is not None and tor is not None:
        return build_trig_table(mode_table, nj=pol.size, nk=1, nper=nfp, pol=pol, tor=tor)
    return build_trig_table(mode_table, nj=nj, nk=nk, nper=nfp)

